def get_network_acl(self, key=None, acl_id=None):
    if acl_id is not None:
        args = {
            'id': acl_id,
            'vpcid': self.get_vpc(key='id'),
        }
    else:
        acl_name = self.module.params.get('acl')
        if not acl_name:
            return

        args = {
            'name': acl_name,
            'vpcid': self.get_vpc(key='id'),
        }
    network_acls = self.query_api('listNetworkACLLists', **args)
    if network_acls:
        acl = network_acls['networkacllist'][0]
        return self._get_by_key(key, acl)

def get_network_offering(self, key=None):
    network_offering = self.module.params.get('network_offering')
    if not network_offering:
        self.module.fail_json(msg="missing required arguments: network_offering")

    args = {
        'zoneid': self.get_zone(key='id'),
        'fetch_list': True,
    }

    network_offerings = self.query_api('listNetworkOfferings', **args)
    if network_offerings:
        for no in network_offerings:
            if network_offering in [no['name'], no['displaytext'], no['id']]:
                return self._get_by_key(key, no)
    self.module.fail_json(msg="Network offering '%s' not found" % network_offering)

def _get_args(self):
    args = {
        'name': self.module.params.get('name'),
        'displaytext': self.get_or_fallback('display_text', 'name'),
        'networkdomain': self.module.params.get('network_domain'),
        'networkofferingid': self.get_network_offering(key='id')
    }
    return args

def get_network(self, refresh=False):
    if not self.network or refresh:
        network = self.module.params.get('name')
        args = {
            'zoneid': self.get_zone(key='id'),
            'projectid': self.get_project(key='id'),
            'account': self.get_account(key='name'),
            'domainid': self.get_domain(key='id'),
            'vpcid': self.get_vpc(key='id'),
            'fetch_list': True,
        }
        networks = self.query_api('listNetworks', **args)
        if networks:
            for n in networks:
                if network in [n['name'], n['displaytext'], n['id']]:
                    self.network = n
                    self.network['acl'] = self.get_network_acl(key='name', acl_id=n.get('aclid'))
                    break
    return self.network

def present_network(self):
    if self.module.params.get('acl') is not None and self.module.params.get('vpc') is None:
        self.module.fail_json(msg="Missing required params: vpc")

    network = self.get_network()
    if not network:
        network = self.create_network(network)
    else:
        network = self.update_network(network)
    return network

def update_network(self, network):
    args = self._get_args()
    args['id'] = network['id']

    if self.has_changed(args, network):
        self.result['changed'] = True
        if not self.module.check_mode:
            network = self.query_api('updateNetwork', **args)

            poll_async = self.module.params.get('poll_async')
            if network and poll_async:
                network = self.poll_job(network, 'network')

    # Skip ACL check if the network is not a VPC tier
    if network.get('aclid') != self.get_network_acl(key='id'):
        self.result['changed'] = True
        if not self.module.check_mode:
            args = {
                'aclid': self.get_network_acl(key='id'),
                'networkid': network['id'],
            }
            network = self.query_api('replaceNetworkACLList', **args)
            if self.module.params.get('poll_async'):
                self.poll_job(network, 'networkacllist')
                network = self.get_network(refresh=True)
    return network

def restart_network(self):
    network = self.get_network()

    if not network:
        self.module.fail_json(msg="No network named '%s' found." % self.module.params('name'))

    # Restarting only available for these states
    if network['state'].lower() in ['implemented', 'setup']:
        self.result['changed'] = True

        args = {
            'id': network['id'],
            'cleanup': self.module.params.get('clean_up')
        }

        if not self.module.check_mode:
            network = self.query_api('restartNetwork', **args)

            poll_async = self.module.params.get('poll_async')
            if network and poll_async:
                network = self.poll_job(network, 'network')
    return network

def absent_network(self):
    network = self.get_network()
    if network:
        self.result['changed'] = True

        args = {
            'id': network['id']
        }

        if not self.module.check_mode:
            res = self.query_api('deleteNetwork', **args)

            poll_async = self.module.params.get('poll_async')
            if res and poll_async:
                self.poll_job(res, 'network')
        return network

def get_result(self, network):
    super(AnsibleCloudStackNetwork, self).get_result(network)
    if network:
        self.result['acl'] = self.get_network_acl(key='name', acl_id=network.get('aclid'))
    return self.result

def main():
    module = DimensionDataNetworkModule()
    if module.state == 'present':
        module.state_present()
    elif module.state == 'absent':
        module.state_absent()

def state_absent(self):
    network = self._get_network()

    if not network:
        self.module.exit_json(
            changed=False,
            msg='Network "%s" does not exist' % self.name,
            network=self._network_to_dict(network)
        )

    self._delete_network(network)

def _get_network(self):
    if self.mcp_version == '1.0':
        networks = self.driver.list_networks(location=self.location)
    else:
        networks = self.driver.ex_list_network_domains(location=self.location)

    matched_network = [network for network in networks if network.name == self.name]
    if matched_network:
        return matched_network[0]

    return None

def _network_to_dict(self, network):
    network_dict = dict(
        id=network.id,
        name=network.name,
        description=network.description
    )

    if isinstance(network.location, NodeLocation):
        network_dict['location'] = network.location.id
    else:
        network_dict['location'] = network.location

    if self.mcp_version == '1.0':
        network_dict['private_net'] = network.private_net
        network_dict['multicast'] = network.multicast
        network_dict['status'] = None
    else:
        network_dict['private_net'] = None
        network_dict['multicast'] = None
        network_dict['status'] = network.status

    return network_dict

def _create_network(self):

    # Make sure service_plan argument is defined
    if self.mcp_version == '2.0' and 'service_plan' not in self.module.params:
        self.module.fail_json(
            msg='service_plan required when creating network and location is MCP 2.0'
        )

    # Create network
    try:
        if self.mcp_version == '1.0':
            network = self.driver.ex_create_network(
                self.location,
                self.name,
                description=self.description
            )
        else:
            network = self.driver.ex_create_network_domain(
                self.location,
                self.name,
                self.module.params['service_plan'],
                description=self.description
            )
    except DimensionDataAPIException as e:

        self.module.fail_json(
            msg="Failed to create new network: %s" % to_native(e), exception=traceback.format_exc()
        )

    if self.module.params['wait'] is True:
        network = self._wait_for_network_state(network.id, 'NORMAL')

    return network

def _delete_network(self, network):
    try:
        if self.mcp_version == '1.0':
            deleted = self.driver.ex_delete_network(network)
        else:
            deleted = self.driver.ex_delete_network_domain(network)

        if deleted:
            self.module.exit_json(
                changed=True,
                msg="Deleted network with id %s" % network.id
            )

        self.module.fail_json(
            "Unexpected failure deleting network with id %s", network.id
        )

    except DimensionDataAPIException as e:
        self.module.fail_json(
            msg="Failed to delete network: %s" % to_native(e), exception=traceback.format_exc()
        )
